mapper.select:
SELECT
    housing_category AS housingCategory,
    is_trust_property AS trustProperty

FROM analysis_reports

WHERE analysis_report_id = #{analysisReportId}
  AND account_id = #{accountId}

SELECT ar.road_address AS roadAddress, ar.detail_address AS detailAddress
FROM analysis_report_checklists arc
INNER JOIN analysis_reports ar ON ar.analysis_report_id = arc.analysis_report_id
WHERE arc.analysis_report_checklist_id = #{reportChecklistId}
AND arc.account_id = #{accountId}

mapper.update:
UPDATE analysis_report_checklist_items rci
INNER JOIN analysis_report_checklists rc ON rc.analysis_report_checklist_id = rci.analysis_report_checklist_id
SET rci.is_checked = #{checked}, rci.modified_at = CURRENT_TIMESTAMP
WHERE rc.analysis_report_checklist_id = #{reportChecklistId}
AND rc.account_id = #{accountId}
AND rci.checklist_item_id = #{checklistItemId}

UPDATE analysis_report_checklist_items rci
INNER JOIN analysis_report_checklists rc ON rc.analysis_report_checklist_id = rci.analysis_report_checklist_id
SET rci.is_checked = TRUE, rci.modified_at = CURRENT_TIMESTAMP
WHERE rc.analysis_report_checklist_id = #{reportChecklistId}
AND rc.account_id = #{accountId}
AND rci.checklist_item_id = #{checklistItemId}

UPDATE analysis_report_checklist_items rci
INNER JOIN analysis_report_checklists rc ON rc.analysis_report_checklist_id = rci.analysis_report_checklist_id
SET rci.is_checked = FALSE, rci.modified_at = CURRENT_TIMESTAMP
WHERE rc.analysis_report_checklist_id = #{reportChecklistId}
AND rc.account_id = #{accountId}

